from autore import Modulo,estratto
from tikz_base import scrivi,n,a,rect,linea
m=Modulo('M14','Estremi, pericolosità e rischio','Superamenti, tempi di ritorno e incertezza dei livelli rari')
def p(t,s,**kw):m.pagina(t,s,**kw)
def d(i,b):return scrivi('M14',i,b)
m.sezione_nuova('Massimi annuali e probabilità empiriche')
p('La variabile estrema e l’unità temporale',
'''La serie comprende cento massimi annuali di portata sintetici, associati agli anni dal 1920 al 2019. Ogni riga rappresenta il maggiore valore di un anno e possiede quindi un significato diverso da una portata media annua o da una misura giornaliera. Prima della modellazione si verificano unicità degli anni, continuità del calendario, unità e valori mancanti. La completezza della tabella rende ricostruibile la sequenza, mentre indipendenza e stazionarietà riguardano proprietà del processo che richiedono una valutazione distinta.''',formula=r'M_y=\max_{t\in\text{anno }y}Q_t',figura='M14/F01',didascalia='Cento massimi annuali simulati, in metri cubi al secondo. Gli anni sono etichette del caso didattico.',richiamo='La definizione del blocco temporale determina la variabile alla quale si applica il modello degli estremi.',origine='M14:1–15')
p('Distribuzione del massimo di un blocco',
'''Se un blocco contenesse m osservazioni indipendenti con la medesima distribuzione F, la probabilità che il massimo sia inferiore a una soglia coinciderebbe con la probabilità che tutte le osservazioni lo siano. Il prodotto delle probabilità produce la potenza m della distribuzione originaria. Questa derivazione chiarisce come l’operazione di massimo modifichi la distribuzione; per serie idrologiche reali, dipendenza e stagionalità impediscono spesso di applicare direttamente la formula. La modellazione dei massimi annuali affronta il blocco come unità di analisi.''',formula=r'P(M_m\le q)=P(Q_1\le q,\ldots,Q_m\le q)=F(q)^m',tikz=d('D01',''.join(rect(.5+k*1.35,1.1,1.65+k*1.35,3.2)+n(1.075+k*1.35,2.15,lab,w=1,size=11) for k,lab in enumerate([r'$Q_1$',r'$Q_2$',r'$\cdots$',r'$Q_m$']))+a(3.1,3.5,3.1,4.3)+n(3.7,5.1,r'$M_m=\max(Q_1,\ldots,Q_m)$',w=6.8)),richiamo='La distribuzione di un massimo dipende dalla dimensione e dalla struttura del blocco.',origine='M14:1–15; approfondimento R5')
p('Posizioni empiriche di superamento',
'''Ordinando i massimi in senso decrescente, si attribuisce al rango r la posizione grafica r diviso n più uno. L’inverso fornisce una scala convenzionale di ritorno sulla quale rappresentare i dati osservati. Il massimo del record occupa così una posizione prossima a centouno anni, senza diventare una stima certa della probabilità dell’evento. Altre convenzioni di posizione grafica possono modificare leggermente i punti, soprattutto agli estremi; la scelta deve essere dichiarata quando si confrontano grafici o software.''',formula=r'\widehat p_r=\frac{r}{n+1},\qquad\widehat T_r=\frac{n+1}{r}',figura='M14/F02',didascalia='Posizioni grafiche r/(n + 1), con asse dei tempi di ritorno in scala logaritmica.',richiamo='Una posizione grafica ordina l’evidenza osservata e conserva l’incertezza dei ranghi estremi.',origine='M14:16–20')
c=estratto('M14','superamento',"d <- read.csv('dati/estremi_v3.csv')\nx <- d$portata_massima_m3s\nq <- 600\nF <- mean(x <= q)\np <- mean(x > q)\nstopifnot(abs(F+p-1) < 1e-12)\ndata.frame(soglia=q,CDF=F,superamento=p)")
p('Distribuzione empirica e soglia di superamento',
'''La distribuzione empirica conta la frazione dei massimi minori o uguali alla soglia, mentre il suo complemento conta quelli strettamente maggiori. La distinzione sull’uguaglianza diventa rilevante quando le misure sono arrotondate e compaiono pareggi. Il codice esplicita entrambi gli eventi e verifica che le proporzioni sommino a uno. La frequenza campionaria ottenuta descrive il record disponibile; la sua interpretazione come probabilità del processo richiede che il campione sia pertinente al periodo e al regime di interesse.''',formula=r'\widehat F_n(q)=\frac1n\sum_i\mathbf1\{M_i\le q\}\qquad\widehat p(q)=1-\widehat F_n(q)',codice=c,richiamo='La convenzione sulla soglia deve essere identica nel conteggio, nel modello e nella comunicazione del risultato.',origine='M14:21–25')
p('Quantili campionari e limite del supporto osservato',
'''Un quantile campionario interpolato, come quello di tipo sette in R, combina valori ordinati del record e rimane entro il loro intervallo. Per probabilità molto elevate, il risultato dipende da pochi massimi e non costruisce automaticamente una coda oltre il valore più grande osservato. Un modello parametrico può produrre quantili esterni al supporto campionario, introducendo ipotesi sulla forma della distribuzione. Il confronto deve quindi distinguere la sintesi dei dati dall’estrapolazione modellistica e riportare la convenzione utilizzata per i quantili empirici.''',formula=r'\min_iM_i\le\widehat Q_n(u)\le\max_iM_i\qquad(0\le u\le1)',destra='Con cento massimi annuali, una probabilità di superamento dell’ordine di un millesimo riguarda eventi più rari della risoluzione empirica del record. Il numero restituito da una formula deve essere valutato rispetto alla distanza dall’informazione osservata.',richiamo='L’estrapolazione richiede ipotesi ulteriori e un’analisi della loro influenza.',origine='M14:41–45')
m.sezione_nuova('Ritorno, attesa e orizzonte temporale')
p('Tempo di ritorno e probabilità annua',
'''Per una soglia fissata e una probabilità annua di superamento costante p, il tempo di ritorno viene definito come il suo inverso. La denominazione centennale corrisponde quindi a p uguale a 0,01 e non impone un intervallo deterministico fra eventi. Due anni consecutivi possono entrambi superare la soglia; nel modello indipendente, l’evento precedente lascia invariata la probabilità del successivo. L’interpretazione richiede di specificare la soglia, il blocco annuale e il regime rispetto al quale la probabilità è considerata stabile.''',formula=r'T(q)=\frac1{P(M_y>q)}=\frac1{1-F_M(q)}',tikz=d('D02',rect(.5,1.2,3.3,3.6)+n(1.9,2.4,r'$p=0,01$',size=18)+a(3.5,2.4,4.1,2.4,'Quantum')+rect(4.3,1.2,7.1,3.6,'Quantum')+n(5.7,2.4,r'$T=100$',size=18)+n(3.7,4.6,'Una probabilità annua, espressa in forma inversa.',w=6.8,size=11)+n(3.7,5.6,'Gli eventi possono essere ravvicinati.',w=6.8,size=11)),richiamo='Il tempo di ritorno è una proprietà probabilistica del modello e della soglia.',origine='M14:26–30')
p('Probabilità di superamento lungo un orizzonte',
'''Con anni indipendenti e identica probabilità p, l’assenza di superamenti per H anni ha probabilità pari a uno meno p elevato a H. Il complemento descrive almeno un superamento durante l’intero orizzonte. Per una soglia centennale, la probabilità è circa 39,5% in cinquant’anni e 63,4% in cento anni. Il numero atteso di superamenti è invece Hp: le due quantità rispondono a domande differenti e possono assumere valori numericamente molto diversi.''',formula=r'P(N_H\ge1)=1-(1-p)^H,\qquad E[N_H]=Hp',figura='M14/F03',didascalia='Probabilità di almeno un evento con p = 0,01 annuo, sotto indipendenza e probabilità costante.',richiamo='La probabilità sull’intero orizzonte deve essere calcolata sulle condizioni temporali del problema.',origine='M14:31–35')
p('Distribuzione geometrica del tempo di attesa',
'''Nel modello di prove annuali indipendenti, l’attesa W fino al primo superamento conta gli anni compreso quello dell’evento. Per attendere esattamente k anni devono verificarsi k meno uno anni senza superamento, seguiti da un anno con superamento. La distribuzione geometrica ha media pari a uno diviso p, mentre la sua asimmetria separa media e mediana. Con p uguale a 0,01 la mediana è sessantanove anni, mentre l’attesa media è cento.''',formula=r'P(W=k)=(1-p)^{k-1}p,\quad k=1,2,\ldots\\ E[W]=\frac1p,\qquad\operatorname{Var}(W)=\frac{1-p}{p^2}',tikz=d('D03',''.join(rect(.5+k*1.3,1.3,1.55+k*1.3,3.3,'Quantum' if k==4 else 'Classical')+n(1.025+k*1.3,2.3,'E' if k==4 else '0',size=16) for k in range(5))+n(3.7,4.4,'Quattro anni senza evento, poi un superamento.',w=6.8,size=11)+n(3.7,5.5,r'$P(W=5)=(1-p)^4p$',size=16)),richiamo='Il valore medio dell’attesa deve essere interpretato insieme alla sua distribuzione.',origine='M14:36–40')
p('Simulazione delle attese e asimmetria',
'''La simulazione genera diecimila attese indipendenti dal modello geometrico, aggiungendo uno ai valori di rgeom, che conta gli insuccessi prima del primo successo. L’istogramma mostra una concentrazione di attese brevi e una coda di attese lunghe, mentre la linea verticale indica la media teorica di cento anni. La simulazione rende visibile il significato del modello, senza verificare che un processo idrologico reale ne soddisfi le ipotesi. La sequenza casuale e la convenzione di conteggio sono incluse nel codice riproducibile.''',figura='M14/F04',didascalia='Diecimila attese simulate con p = 0,01. La linea viola indica cento anni; il supporto inizia da uno.',richiamo='Il conteggio degli insuccessi e quello degli anni fino all’evento differiscono di una unità.',origine='M14:36–40')
p('Probabilità variabile e dipendenza fra anni',
'''Se la probabilità cambia nel tempo ma gli anni restano indipendenti, la probabilità di nessun superamento è il prodotto dei complementi delle probabilità annuali. Un unico tempo di ritorno costante non riassume più l’intero periodo. Quando vi è dipendenza, anche tale prodotto richiede una sostituzione con probabilità condizionate o con un modello congiunto. La valutazione di lungo periodo deve quindi considerare cambiamenti del processo, modifiche del bacino e persistenza, oltre all’incertezza nella stima dei parametri.''',formula=r'P(N_H\ge1)=1-\prod_{t=1}^{H}(1-p_t)',tikz=d('D04',a(.6,4.5,6.8,4.5)+''.join(rect(1+k*1.5,4.5-h,1.9+k*1.5,4.5,'Quantum' if k>1 else 'Classical')+n(1.45+k*1.5,5.1,lab,size=11) for k,(h,lab) in enumerate([(1,r'$p_1$'),(1.5,r'$p_2$'),(2.3,r'$p_3$'),(3,r'$p_4$')]))+n(3.7,.6,'Probabilità annuali di scenario',w=6.8)),richiamo='La stazionarietà e l’indipendenza svolgono ruoli distinti nelle formule di probabilità temporale.',origine='M14:26–40,81–85; approfondimento R5')
m.sezione_nuova('Modello Gumbel e verifica dell’adattamento')
p('Gumbel per massimi: posizione e scala',
'''La distribuzione Gumbel per massimi descrive una famiglia con parametro di posizione a e parametro di scala b positivo. La funzione cumulativa aumenta da zero a uno, mentre la trasformazione interna determina una coda destra asimmetrica. Il modello è una possibile approssimazione dei massimi di blocco, la cui pertinenza deve essere valutata rispetto al processo e ai dati. La parametrizzazione per massimi deve essere distinta da quella per minimi, poiché un’inversione dei segni modifica la direzione della coda.''',formula=r'F(q)=\exp\!\left[-\exp\!\left(-\frac{q-a}{b}\right)\right],\qquad b>0',destra='La media è a + γb e la deviazione standard è bπ/√6, dove γ ≈ 0,577216 è la costante di Eulero–Mascheroni. Nella Gumbel il parametro di posizione e la media hanno valori differenti.',richiamo='Parametrizzazione, unità e direzione dell’estremo devono essere coerenti in tutte le formule.',fonti='NIST: distribuzione dei valori estremi I',origine='M14:46–55')
c=estratto('M14','momenti',"x <- read.csv('dati/estremi_v3.csv')$portata_massima_m3s\ngamma <- .5772156649015329\nb <- sd(x)*sqrt(6)/pi\na <- mean(x)-gamma*b\nstopifnot(b > 0)\nc(posizione=a,scala=b)")
p('Stima basata sui momenti campionari',
'''La stima utilizzata nel laboratorio ricava la scala dalla deviazione standard campionaria e la posizione dalla media, sfruttando le relazioni teoriche della Gumbel. La deviazione standard di R impiega il denominatore n meno uno, convenzione che viene mantenuta nel codice. Per il record sintetico si ottengono a circa 476,26 e b circa 82,96 metri cubi al secondo. Questa procedura basata sui momenti è semplice da verificare manualmente e rimane distinta dalla massima verosimiglianza, che richiede un’ottimizzazione della funzione di verosimiglianza.''',formula=r'\widehat b=s\frac{\sqrt6}{\pi},\qquad\widehat a=\overline M-\gamma\widehat b',codice=c,richiamo='La procedura di stima e le convenzioni campionarie devono accompagnare i parametri.',origine='M14:46–50')
c=estratto('M14','inversione',"x <- read.csv('dati/estremi_v3.csv')$portata_massima_m3s\nb <- sd(x)*sqrt(6)/pi\na <- mean(x)-.5772156649015329*b\nu <- c(.1,.5,.9,.99)\nq <- a-b*log(-log(u))\nF <- exp(-exp(-(q-a)/b))\nstopifnot(max(abs(F-u)) < 1e-12)\ndata.frame(u,q,F)")
p('Quantile Gumbel e controllo dell’inversione',
'''Invertendo la funzione cumulativa si ottiene il quantile per probabilità comprese strettamente fra zero e uno. Il doppio logaritmo rende essenziale il controllo dei segni e del dominio: una probabilità esterna all’intervallo produrrebbe valori indefiniti. Il codice verifica che la composizione della distribuzione con il quantile restituisca le probabilità iniziali entro la tolleranza numerica. Tale identità controlla l’implementazione algebrica e deve essere distinta dall’adeguatezza del modello ai massimi osservati.''',formula=r'Q(u)=a-b\log[-\log(u)],\qquad F[Q(u)]=u',codice=c,richiamo='Una formula correttamente implementata può restare statisticamente inadeguata al processo studiato.',origine='M14:51–55')
p('Distribuzione cumulativa empirica e adattata',
'''Il confronto sovrappone la funzione empirica, che procede per salti di ampiezza uno su cento, alla distribuzione Gumbel stimata. La corrispondenza complessiva aiuta a riconoscere scostamenti di posizione e dispersione, ma la scala cumulativa può rendere poco evidenti divergenze nella coda estrema. La valutazione deve perciò integrare rappresentazioni mirate ai quantili alti e analisi di sensibilità. La distribuzione empirica e quella adattata utilizzano lo stesso record, circostanza da ricordare nell’interpretazione della concordanza.''',figura='M14/F06',didascalia='Verde: distribuzione empirica dei cento massimi. Viola: Gumbel stimata mediante i momenti campionari.',richiamo='La concordanza centrale deve essere accompagnata da una verifica della coda pertinente al problema.',origine='M14:21–25,46–60')
p('Diagramma quantile–quantile e coda',
'''Il diagramma confronta massimi ordinati e quantili Gumbel calcolati alle stesse posizioni di probabilità. Una corrispondenza sulla diagonale indica accordo locale fra le due scale, mentre curvature o scostamenti agli estremi suggeriscono differenze nella forma della distribuzione. I punti di coda sono pochi e variabili, per cui una deviazione isolata richiede un esame dell’evento e della qualità della misura. La diagnostica deve essere collegata ai livelli che si vogliono stimare, poiché un buon adattamento centrale può coesistere con incertezza elevata sui valori rari.''',figura='M14/F05',didascalia='Quantili teorici alle posizioni (i − 0,5)/n; la diagonale rappresenta l’uguaglianza fra quantile teorico e osservato.',richiamo='La coda della distribuzione richiede un esame specifico, proporzionato alla scarsità dell’informazione.',origine='M14:56–60')
m.sezione_nuova('Livelli rari e incertezza della stima')
p('Livelli di ritorno ed estrapolazione',
'''Il livello associato al tempo di ritorno T è il quantile con probabilità cumulativa uno meno uno su T. La Gumbel stimata restituisce circa 857,90 metri cubi al secondo per cento anni e 991,75 per cinquecento anni. Quest’ultimo orizzonte supera la lunghezza del record e rende più forte la dipendenza dalla forma della coda. La curva viene quindi affiancata ai punti empirici e a una regione che segnala i tempi oltre cento anni, affinché l’estrapolazione rimanga visibile.''',formula=r'q_T=a-b\log[-\log(1-1/T)],\qquad T>1',figura='M14/F07',didascalia='Curva Gumbel e posizioni empiriche; il fondo viola segnala tempi di ritorno superiori ai cento anni osservati.',richiamo='L’orizzonte di ritorno deve essere confrontato con la durata e con la qualità del record.',origine='M14:61–65')
p('Il ricampionamento ripete l’intera stima',
'''Nel bootstrap dei massimi annuali si estraggono anni con reinserimento e, per ogni campione, si ristimano posizione, scala e livello centennale. Mantenere fissi i parametri durante il ricampionamento escluderebbe proprio la componente di variabilità che si vuole esaminare. La revisione utilizza 1999 ripetizioni con seme documentato, mentre il laboratorio originario conserva cento estrazioni condivise per il confronto fra linguaggi. L’interpretazione del bootstrap richiede che gli anni possano essere trattati come unità scambiabili sotto un regime stabile.''',tikz=d('D05',rect(.5,.6,6.9,1.9)+n(3.7,1.25,'Campione di cento massimi annuali',w=6)+a(3.7,2.1,3.7,2.6)+rect(.5,2.8,6.9,4.1,'Quantum')+n(3.7,3.45,r'Nuovo campione e nuovi $\widehat a,\widehat b$',w=6,size=11.5)+a(3.7,4.3,3.7,4.8)+n(3.7,5.4,r'Nuovo livello $\widehat q_{100}$',w=6,size=15)),richiamo='Ogni ripetizione deve comprendere tutti i passaggi di stima che dipendono dal campione.',origine='M14:66–70')
p('Distribuzione bootstrap del livello centennale',
'''I quantili al 2,5% e 97,5% della distribuzione bootstrap sono circa 789,16 e 923,10 metri cubi al secondo. L’intervallo percentile descrive la variabilità della procedura sotto le ipotesi di ricampionamento e di modello, senza includere automaticamente cambiamenti futuri del processo o incertezza sulla scelta della famiglia. La dispersione attorno alla stima puntuale rende visibile quanto il livello dipenda dal record finito. Il numero di ripetizioni controlla la precisione Monte Carlo dei quantili e non sostituisce l’informazione osservativa mancante.''',figura='M14/F08',didascalia='1999 stime bootstrap del livello centennale. La linea viola indica la stima sul record completo.',richiamo='L’incertezza campionaria deve essere distinta dall’incertezza sulla struttura e sulla stabilità del modello.',origine='M14:66–70')
p('Lunghezza del record e stabilità dei parametri',
'''La stima del livello centennale viene ripetuta utilizzando i primi venti, quaranta, sessanta, ottanta e cento anni. I campioni sono annidati e condividono gran parte delle osservazioni, cosicché i punti della curva non rappresentano esperimenti indipendenti. Le oscillazioni mostrano la sensibilità alla quantità di informazione disponibile e agli estremi progressivamente inclusi. Un tratto apparentemente stabile può essere rassicurante sul campione esaminato, ma non dimostra che il processo resterà invariato né che la famiglia scelta descriva correttamente la coda.''',figura='M14/F09',didascalia='Stime su prefissi crescenti dello stesso record sintetico. Il periodo iniziale è comune a tutti i campioni.',richiamo='La stabilità su campioni annidati è una diagnosi di sensibilità, da interpretare insieme alle ipotesi del modello.',origine='M14:71–75')
p('Influenza del massimo e verifica dell’osservazione',
'''Aumentando del trenta per cento il massimo in una copia del record, il livello centennale passa da circa 857,90 a 897,27 metri cubi al secondo. Il confronto quantifica l’influenza di un’estremità campionaria sulla stima dei momenti, mantenendo intatti i dati originari. Un valore influente può essere un errore di misura oppure un evento raro pertinente alla coda, per cui l’eliminazione richiede evidenze indipendenti. La relazione dovrebbe documentare il controllo dell’evento e l’effetto delle decisioni alternative sulla conclusione.''',tikz=d('D06',rect(.5,1.1,3.3,3.5)+rect(4.1,1.1,6.9,3.5,'Quantum')+n(1.9,2.3,r'Originale\par857,90 m³/s',w=2.5,size=11)+n(5.5,2.3,r'Massimo +30\%\par897,27 m³/s',w=2.5,size=11)+n(3.7,4.6,'Livello centennale stimato nei due casi',w=6.8,size=11)+n(3.7,5.6,'La verifica riguarda l’evento e la sua misura.',w=6.8,size=11)),richiamo='L’influenza di un estremo richiede un controllo documentato, senza cancellarne automaticamente l’informazione.',origine='M14:76–80')
p('Confronto fra periodi e attribuzione dei cambiamenti',
'''Le due metà del record comprendono cinquanta anni ciascuna e possono mostrare medie e dispersioni differenti anche quando il processo generatore è costante, come nella simulazione inclusa. Il confronto descrittivo deve precedere ogni attribuzione a cambiamenti climatici, uso del suolo o opere nel bacino. Per dati osservativi, metadati, omogeneità delle misure e ipotesi sulle forzanti sono necessari a distinguere variabilità campionaria e cambiamento del processo. Una suddivisione scelta dopo avere osservato il massimo contrasto introduce inoltre un effetto di selezione.''',formula=r'\Delta\overline M=\overline M_{1970:2019}-\overline M_{1920:1969}',destra='Un’indagine temporale può includere covariate, modelli non stazionari e controlli di sensibilità, purché la complessità sia sostenuta dall’informazione disponibile. La differenza fra due statistiche descrittive costituisce un punto di partenza per l’analisi, non una spiegazione causale.',richiamo='La descrizione di una differenza temporale deve essere separata dall’identificazione del suo meccanismo.',origine='M14:81–85')
m.sezione_nuova('Forma della coda e sensibilità GEV')
p('La famiglia generalizzata dei valori estremi',
'''La GEV aggiunge un parametro di forma xi, che controlla il comportamento della coda oltre a posizione e scala. La distribuzione è definita dove il termine di supporto rimane positivo, mentre il limite per xi tendente a zero restituisce la Gumbel. Una forma positiva produce una coda superiore più pesante; una forma negativa introduce un estremo superiore finito. L’incertezza di xi può influenzare fortemente i livelli con tempi di ritorno lunghi.''',formula=r'F(q)=\exp\left\{-\left[1+\xi\frac{q-\mu}{\sigma}\right]^{-1/\xi}\right\}\\ \sigma>0,\qquad1+\xi(q-\mu)/\sigma>0',tikz=d('D07',n(3.7,.7,'Tre comportamenti della coda')+rect(.5,1.7,6.9,2.8)+n(3.7,2.25,r'$\xi<0$: limite superiore finito',w=6,size=12)+rect(.5,3,6.9,4.1,'Quantum')+n(3.7,3.55,r'$\xi=0$: limite Gumbel',w=6,size=12)+rect(.5,4.3,6.9,5.4,'Measure')+n(3.7,4.85,r'$\xi>0$: coda superiore pesante',w=6,size=12)),richiamo='Il parametro di forma modifica sia il supporto sia l’estrapolazione della coda.',fonti='evd: distribuzione GEV',origine='M14:86–90')
p('Scenari di forma a posizione e scala fissate',
'''Il confronto mantiene posizione pari a 480 e scala pari a 90, variando xi fra meno 0,15, zero e più 0,15. I valori sono ipotesi di sensibilità e non stime aggiuntive dal record. Le curve divergono soprattutto ai tempi di ritorno elevati, rendendo visibile la dipendenza dell’estrapolazione dalla forma della coda. Quando si confrontano implementazioni, occorre verificare anche il segno del parametro: alcune librerie utilizzano una convenzione opposta per la forma, pur rappresentando la stessa famiglia di distribuzioni.''',formula=r'q_T=\mu+\frac{\sigma}{\xi}\{[-\log(1-1/T)]^{-\xi}-1\},\quad\xi\ne0',figura='M14/F10',didascalia='Scenari GEV con posizione 480 e scala 90 m³/s. Le tre forme sono prefissate e non adattate ai dati.',richiamo='La sensibilità alla forma deve accompagnare la comunicazione dei livelli molto rari.',origine='M14:86–90')
m.sezione_nuova('Superamenti giornalieri ed episodi')
p('Giorni sopra soglia e numero degli episodi',
'''La breve serie giornaliera sintetica contiene sei valori superiori alla soglia dieci, organizzati in due sequenze consecutive. Contare i giorni misura la durata discreta del superamento, mentre contare le sequenze individua episodi secondo una regola temporale. Entrambe le quantità possono essere utili, ma rispondono a domande differenti. La distinzione diventa essenziale quando un modello per eventi richiede approssimativa indipendenza: più giorni della stessa piena non costituiscono automaticamente più episodi indipendenti.''',formula=r'N_{\rm giorni}=\sum_t\mathbf1\{Q_t>u\}=6',figura='M14/F11',didascalia='Soglia u = 10 nelle unità arbitrarie della serie. I sei punti viola appartengono a due sequenze.',richiamo='La definizione operativa di evento deve precedere il conteggio e il modello probabilistico.',origine='M14:91–95')
c=estratto('M14','episodi',"q <- c(2,3,4,12,14,11,5,4,3,2,\n 3,12,15,13,5,4,2,1,3,2)\nex <- q > 10\nstart <- ex & !c(FALSE,head(ex,-1))\ngr <- cumsum(start)\npicchi <- aggregate(q~gr,\n data.frame(q=q[ex],gr=gr[ex]),max)\nstopifnot(sum(ex)==6,sum(start)==2,\n identical(picchi$q,c(14,15)))\npicchi")
p('Separazione delle sequenze e picchi di evento',
'''La regola didattica apre un episodio quando un giorno sopra soglia segue un giorno che non la supera, quindi assegna lo stesso gruppo ai superamenti consecutivi. Di ogni gruppo si conserva il massimo, ottenendo picchi pari a quattordici e quindici. Un’analisi idrologica reale può richiedere una separazione minima più lunga e criteri fondati sulla dinamica del bacino. La regola deve essere scelta prima della stima degli estremi, poiché modifica frequenza degli eventi, distribuzione dei picchi e interpretazione dei tempi di ritorno.''',codice=c,richiamo='La separazione degli episodi deve riflettere la scala di dipendenza del processo.',origine='M14:96–100')
p('Due strategie per costruire il campione degli estremi',
'''Il metodo dei massimi di blocco conserva un solo valore per intervallo temporale, mentre il metodo dei superamenti di soglia seleziona episodi eccedenti un livello prefissato. Il secondo richiede di definire soglia, separazione degli episodi e frequenza di occorrenza, potendo conservare più informazione sugli eventi rari. I due approcci non condividono automaticamente la stessa numerosità né la stessa interpretazione temporale. Il corso usa i massimi annuali per la stima Gumbel e introduce i superamenti giornalieri per chiarire la costruzione del campione.''',tikz=d('D08',rect(.5,.8,6.9,2)+n(3.7,1.4,'Serie osservata con risoluzione dichiarata',w=6,size=11)+a(2.1,2.2,2.1,3.1)+a(5.3,2.2,5.3,3.1,'Quantum')+rect(.5,3.3,3.5,5.2)+rect(3.9,3.3,6.9,5.2,'Quantum')+n(2,4.25,r'Massimo\par per blocco',w=2.6)+n(5.4,4.25,r'Picchi\par sopra soglia',w=2.6)+n(3.7,5.9,'Campioni costruiti mediante regole differenti.',w=6.8,size=11)),richiamo='La scelta del campione degli estremi precede quella della distribuzione da adattare.',origine='M14:91–100; approfondimento R5')
m.sezione_nuova('Pericolosità, conseguenze e comunicazione')
p('Pericolosità, esposizione e conseguenze',
'''La pericolosità descrive la probabilità e l’intensità del fenomeno, mentre le conseguenze dipendono da ciò che è esposto e dalla sua vulnerabilità. Un identico livello di piena può quindi produrre perdite differenti in territori con beni, persone e protezioni diversi. Nel caso didattico vengono assegnati danni ipotetici a classi di evento mutuamente esclusive, rendendo esplicito il passaggio dalla probabilità alla perdita. Il risultato è uno scenario numerico e non una valutazione utilizzabile per un’opera o per un sito reale.''',tikz=d('D09',rect(.5,.7,6.9,2)+n(3.7,1.35,'Probabilità e intensità del fenomeno',w=6,size=11.5)+a(3.7,2.2,3.7,2.7)+rect(.5,2.9,6.9,4.2,'Quantum')+n(3.7,3.55,'Esposizione e vulnerabilità',w=6)+a(3.7,4.4,3.7,4.9)+n(3.7,5.5,'Distribuzione delle conseguenze',w=6.7)),richiamo='La probabilità di un evento deve essere collegata a un modello esplicito delle sue conseguenze.',origine='M14:101–105')
p('Perdita attesa su classi mutuamente esclusive',
'''Le tre classi hanno probabilità annue pari a 0,08, 0,015 e 0,005, con danni ipotetici di diecimila, centomila e un milione di unità monetarie. Il restante novanta per cento viene associato a danno nullo nello scenario. I contributi attesi sono rispettivamente 800, 1500 e 5000, per un totale di 7300 unità monetarie per anno. La classe meno frequente fornisce il contributo maggiore a causa del danno assegnato. Usare probabilità cumulative sovrapposte al posto di classi esclusive conterebbe più volte parte degli eventi.''',formula=r'E[L]=\sum_k p_k\ell_k=7300\quad\text{unità monetarie/anno}',figura='M14/F12',didascalia='Contributi di tre classi esclusive alla perdita attesa dello scenario. Probabilità e danni sono ipotetici.',richiamo='La somma dei contributi richiede classi compatibili con la definizione probabilistica della perdita.',origine='M14:101–105')
p('Relazione finale e percorso di laboratorio',
'''La relazione presenta variabile estrema, periodo, unità, controlli del record, famiglia, metodo di stima, diagnostica e incertezza, distinguendo risultati osservati ed estrapolati. I laboratori N01–N07 sviluppano probabilità empiriche, ritorno e attese; N08–N12 affrontano Gumbel e bootstrap; N13–N16 esaminano sensibilità e forma della coda; N17–N20 completano episodi, perdita e consegna. Lo studio autonomo confronti il livello centennale con quello cinquecentennale, spiegando quali conclusioni dipendano maggiormente dalle ipotesi sulla coda e sulla stabilità temporale.''',tikz=d('D10',rect(.5,.6,6.9,1.9)+n(3.7,1.25,'Record e definizione dell’estremo',w=6)+a(3.7,2.1,3.7,2.6)+rect(.5,2.8,6.9,4.1,'Quantum')+n(3.7,3.45,'Stima, diagnostica e sensibilità',w=6)+a(3.7,4.3,3.7,4.8)+n(3.7,5.4,'Livelli con ipotesi e dominio dichiarati',w=6.8,size=11.5)),richiamo='La comunicazione di un livello raro deve rendere riconoscibili evidenza, incertezza e condizioni di validità.',origine='M14:1–10,106–110')
m.salva()
